// Strip null/undefined entries from each item (mirrors gsheet 'Clean Nulls')
for (const item of $input.all()) {
  const cleaned = Object.fromEntries(
    Object.entries(item.json).filter(([, v]) => v !== null && v !== undefined)
  );
  item.json = cleaned;
}
return $input.all();

// If any selection / AI field is being set, force a re-sync to Priority
// (mirrors gsheet 'Check Priority Sync')
const fieldsToCheck = [
  'SELECTED_COMPANY_ID',
  'SELECTED_DOC_DATE',
  'AI_DOC_ID',
  'SELECTED_DOC_ID',
  'SELECTED_DOC_AMOUNT',
  'SELECTED_DOC_SHIPMENT_ID',
  'SELECTED_DOC_ORDER_ID',
  'LINK',
  'TYPE',
  'SOURCE_TYPE',
  'FROM_OFFICE_CHECK',
  'SELECTION_CERTAINTY'
];

for (const item of $input.all()) {
  const isUpdated = fieldsToCheck.some(f => item.json[f] !== undefined && item.json[f] !== null);
  if (isUpdated) {
    item.json.PRIORITY_SYNC_COMPLETED = false;
  }
}
return $input.all();

// ============================================================================
// BUILD LOOKUP QUERY — Supabase GET(s) returning every existing row that
// matches ANY input item by one of:
//   1. id (numeric Supabase PK, if caller passes it back)
//   2. COMPANY_ID + SHORT_DOC_ID
//   3. COMPANY_ID + COMPANY_DOC_ID
//   4. HASH
//
// BATCH SUPPORT: chunks the OR filter into multiple URLs (CHUNK_SIZE OR
// clauses each) so PostgREST URL-length limits (~8KB on most reverse proxies)
// don't cap batch size. Emits one item per chunk; the HTTP node calls each;
// Resolve & Prepare Records aggregates `$input.all()`.
//
// If the batch has no usable lookup keys, emits a single `skipLookup: true`
// item (Has Lookup Keys? IF routes around the HTTP call).
// ============================================================================

const SUPABASE_URL = 'https://krvdyzrwstcqrvsaizrk.supabase.co';
const TABLE = 'incoming-documents';
const SELECT_COLS = 'id,COMPANY_ID,SHORT_DOC_ID,COMPANY_DOC_ID,HASH';
const CHUNK_SIZE  = 50;

function has(v) {
  return v !== undefined && v !== null && v !== '' && String(v).toLowerCase() !== 'unknown';
}

// PostgREST value quoting: wrap in double-quotes, escape inner quotes & backslashes
function q(v) {
  return '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}

const items = $input.all().map(i => i.json);

const ids        = new Set();
const hashes     = new Set();
const pairsShort = [];
const pairsDoc   = [];

for (const it of items) {
  const pk = it.id ?? it.ID;
  if (has(pk) && /^\d+$/.test(String(pk))) ids.add(String(pk));
  if (has(it.HASH)) hashes.add(String(it.HASH));
  if (has(it.COMPANY_ID) && has(it.SHORT_DOC_ID))   pairsShort.push({ c: it.COMPANY_ID, s: it.SHORT_DOC_ID });
  if (has(it.COMPANY_ID) && has(it.COMPANY_DOC_ID)) pairsDoc.push({   c: it.COMPANY_ID, d: it.COMPANY_DOC_ID });
}

const orParts = [];
if (ids.size)    orParts.push(`id.in.(${[...ids].join(',')})`);
if (hashes.size) orParts.push(`HASH.in.(${[...hashes].map(q).join(',')})`);
for (const p of pairsShort) orParts.push(`and(COMPANY_ID.eq.${q(p.c)},SHORT_DOC_ID.eq.${q(p.s)})`);
for (const p of pairsDoc)   orParts.push(`and(COMPANY_ID.eq.${q(p.c)},COMPANY_DOC_ID.eq.${q(p.d)})`);

if (!orParts.length) {
  return [{ json: { skipLookup: true, itemCount: items.length } }];
}

const chunks = [];
for (let i = 0; i < orParts.length; i += CHUNK_SIZE) chunks.push(orParts.slice(i, i + CHUNK_SIZE));

return chunks.map((chunk, idx) => ({
  json: {
    skipLookup: false,
    itemCount: items.length,
    chunkIndex: idx,
    chunkCount: chunks.length,
    lookupUrl: `${SUPABASE_URL}/rest/v1/${TABLE}?select=${SELECT_COLS}&or=(${chunk.join(',')})`
  }
}));

// ============================================================================
// RESOLVE & PREPARE RECORDS  (single PK = Supabase `id`)
// ----------------------------------------------------------------------------
// Inputs:
//   - 'Check Priority Sync' .all()  → cleaned input items
//   - this node's input              → existing rows from Supabase lookup
//                                      (may be MULTIPLE items, one per chunk;
//                                       empty when 'Has Lookup Keys?' was false)
//
// Match priority (UPDATE if hit, otherwise INSERT — let Supabase auto-assign id):
//   1. id (or legacy `ID`) provided AND found
//   2. COMPANY_ID + SHORT_DOC_ID match
//   3. COMPANY_ID + COMPANY_DOC_ID match
//   4. HASH match
//
// AUTO TYPE COERCION (boolean / numeric / jsonb / text) is applied per
// EXPECTED schema before sending to Supabase, so PostgREST won't reject
// values like "true", "2,435.00", or stringified arrays.
//
// Output: single item with `records[]` (ready to upsert), `updatedIds[]`,
// stats, warnings.
// ============================================================================

const MAX_BATCH = 1000;

const STRIP_KEYS = new Set(['ID', 'row_number']);

// Mirror of Analyze Schema EXPECTED — used for type coercion.
const EXPECTED = {
  id: 'bigint',
  NAME:'text', COMPANY_ID:'text', SHORT_DOC_ID:'text', TYPE:'text', STATUS:'text',
  COMPANY_DOC_ID:'text', LINK:'text', DOC_DATE:'text', PURCHASE_ID:'text',
  SHIPMENT_DOC_ID:'text', BS_LINE_DATE:'text', SOURCE_TYPE:'text', SOURCE_ID:'text',
  SOURCE_LINK:'text', HASH:'text', TIMESTAMP:'text', COMPANY_NAME:'text',
  REQUIRED_ACTION:'text', BS_LINE_NOTE:'text', FROM_OFFICE:'text', API_TOOLS_ID:'text',
  EX_INVOICE_ID:'text', AI_COMPANY_ID:'text', AI_TYPE:'text', AI_DOC_ID:'text',
  AI_DOC_DATE:'text', SELECTED_COMPANY_ID:'text', SELECTED_DOC_ID:'text',
  SELECTED_DOC_DATE:'text', SELECTED_DOC_SHIPMENT_ID:'text', SELECTED_DOC_ORDER_ID:'text',
  SELECTION_SOURCE:'text',
  DOC_TOTAL_AMOUNT:'numeric', BS_LINE_AMOUNT:'numeric', TOTAL_AMOUNT:'numeric',
  AI_DOC_AMOUNT:'numeric', SELECTED_DOC_AMOUNT:'numeric', SIZE:'numeric',
  SELECTION_CERTAINTY:'numeric',
  LINKED_BS:'boolean', BS_EXTRACTION_VERIFIED:'boolean', FROM_OFFICE_CHECK:'boolean',
  BS_LINK_DOCUMENTS_COMPLETED:'boolean', SEARCH_IN_DRIVE_COMPLETED:'boolean',
  DOC_DATE_COMPLETED:'boolean', DOC_TOTAL_AMOUNT_COMPLETED:'boolean',
  PURCHASE_ID_COMPLETED:'boolean', SHIPMENT_ID_COMPLETED:'boolean',
  COMPANY_NAME_COMPLETED:'boolean', API_TOOLS_ID_COMPLETED:'boolean', EMPTY:'boolean',
  BS_EXTRACTED_LINES_COMPLETED:'boolean', BS_EXTRACTION_USE_CACHE:'boolean',
  INVOICE_ID_COMPLETED:'boolean', EX_IS_BS:'boolean', EX_IS_BS_COMPLETED:'boolean',
  FIGURE_TYPE_COMPLETED:'boolean', FIGURE_COMPANY_COMPLETED:'boolean',
  AI_EXTRACTION_COMPLETED:'boolean', PRIORITY_SYNC_COMPLETED:'boolean',
  SELECTION_COMPLETED:'boolean',
  BS_EXTRACTED_LINES:'jsonb', AI_SHIPMENT_IDS:'jsonb', AI_ORDER_IDS:'jsonb',
  DOUBLE_LINE_CONTEXT:'jsonb', SELECTION_SCORE_DEBUG:'jsonb'
};

function has(v) {
  return v !== undefined && v !== null && v !== '' && String(v).toLowerCase() !== 'unknown';
}
function norm(v) {
  return v === undefined || v === null ? '' : String(v).toLowerCase();
}

// AUTO TYPE COERCION — returns { value, warning|null }. On failure returns the
// original value (PostgREST will surface the column) — we never silently drop.
function coerce(name, v) {
  if (v === null || v === undefined || v === '') return { value: null, warning: null };
  const t = EXPECTED[name];
  if (!t) return { value: typeof v === 'object' ? JSON.stringify(v) : v, warning: null };

  if (t === 'boolean') {
    if (typeof v === 'boolean') return { value: v, warning: null };
    const s = String(v).trim().toLowerCase();
    if (['true','1','yes','y','t'].includes(s))  return { value: true,  warning: null };
    if (['false','0','no','n','f'].includes(s))  return { value: false, warning: null };
    return { value: v, warning: `${name}: cannot coerce "${v}" to boolean` };
  }

  if (t === 'numeric' || t === 'bigint') {
    if (typeof v === 'number') return { value: v, warning: null };
    const cleaned = String(v).replace(/,/g, '').trim();
    if (cleaned === '') return { value: null, warning: null };
    const n = Number(cleaned);
    if (Number.isFinite(n)) return { value: t === 'bigint' ? Math.trunc(n) : n, warning: null };
    return { value: v, warning: `${name}: cannot coerce "${v}" to ${t}` };
  }

  if (t === 'jsonb') {
    if (Array.isArray(v) || (typeof v === 'object' && v !== null)) return { value: v, warning: null };
    if (typeof v === 'string') {
      const s = v.trim();
      if (s.startsWith('[') || s.startsWith('{')) {
        try { return { value: JSON.parse(s), warning: null }; }
        catch (e) { return { value: [s], warning: `${name}: jsonb parse failed, wrapped string in array` }; }
      }
      return { value: [s], warning: null };
    }
    return { value: [v], warning: null };
  }

  // text (default)
  if (typeof v === 'object') return { value: JSON.stringify(v), warning: null };
  return { value: String(v), warning: null };
}

// --- gather inputs ---
const items = $('Check Priority Sync').all().map(i => i.json);

// Aggregate existing rows across (potentially multiple) lookup chunks.
let existing = [];
for (const inp of $input.all()) {
  const j = inp.json;
  if (!j) continue;
  if (Array.isArray(j))           existing.push(...j);
  else if (Array.isArray(j.data)) existing.push(...j.data);
  else if (j.id !== undefined)    existing.push(j);
}
existing = existing.filter(r => r && r.id !== undefined && r.id !== null);

if (!items.length) {
  return [{ json: { success: true, upsertCount: 0, message: 'No items provided', records: [], updatedIds: [], stats: {} } }];
}
if (items.length > MAX_BATCH) {
  return [{ json: { success: false, error: `Batch size ${items.length} exceeds limit ${MAX_BATCH}`, records: [], updatedIds: [] } }];
}

// --- build lookup indexes over existing rows ---
const byId        = new Map();
const byCompShort = new Map();
const byCompDoc   = new Map();
const byHash      = new Map();

for (const r of existing) {
  byId.set(String(r.id), r);
  if (has(r.HASH)) byHash.set(norm(r.HASH), r);
  if (has(r.COMPANY_ID) && has(r.SHORT_DOC_ID))
    byCompShort.set(`${norm(r.COMPANY_ID)}||${norm(r.SHORT_DOC_ID)}`, r);
  if (has(r.COMPANY_ID) && has(r.COMPANY_DOC_ID))
    byCompDoc.set(`${norm(r.COMPANY_ID)}||${norm(r.COMPANY_DOC_ID)}`, r);
}

const stats = { total: items.length, byId: 0, byCompanyShort: 0, byCompanyDoc: 0, byHash: 0, created: 0, rejected: 0, coerced: 0 };
const warnings  = [];
const errors    = [];
const records   = [];
const updatedIds = [];

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  let resolvedId = null;
  let matchMethod = null;

  // 1. direct id (or legacy ID). If caller supplied an id, it MUST exist —
  //    Supabase identity columns accept explicit values, so we reject
  //    unknown ids to prevent inserting with a stale id.
  const rawPk = item.id ?? item.ID;
  if (has(rawPk)) {
    if (!/^\d+$/.test(String(rawPk))) {
      stats.rejected++;
      errors.push(`Item #${idx}: id "${rawPk}" is not numeric (Supabase id is bigint)`);
      continue;
    }
    const hit = byId.get(String(rawPk));
    if (!hit) {
      stats.rejected++;
      errors.push(`Item #${idx}: id "${rawPk}" not found — refusing to insert with caller-supplied id`);
      continue;
    }
    resolvedId = hit.id;
    matchMethod = 'id';
    stats.byId++;
  }

  if (resolvedId === null && has(item.COMPANY_ID) && has(item.SHORT_DOC_ID)) {
    const hit = byCompShort.get(`${norm(item.COMPANY_ID)}||${norm(item.SHORT_DOC_ID)}`);
    if (hit) { resolvedId = hit.id; matchMethod = 'company-short'; stats.byCompanyShort++; }
  }
  if (resolvedId === null && has(item.COMPANY_ID) && has(item.COMPANY_DOC_ID)) {
    const hit = byCompDoc.get(`${norm(item.COMPANY_ID)}||${norm(item.COMPANY_DOC_ID)}`);
    if (hit) { resolvedId = hit.id; matchMethod = 'company-doc'; stats.byCompanyDoc++; }
  }
  if (resolvedId === null && has(item.HASH)) {
    const hit = byHash.get(norm(item.HASH));
    if (hit) { resolvedId = hit.id; matchMethod = 'hash'; stats.byHash++; }
  }

  // --- Uniqueness guard against DIFFERENT existing rows ---
  const collisions = [];
  if (has(item.COMPANY_ID) && has(item.SHORT_DOC_ID)) {
    const hit = byCompShort.get(`${norm(item.COMPANY_ID)}||${norm(item.SHORT_DOC_ID)}`);
    if (hit && hit.id !== resolvedId) collisions.push(`COMPANY_ID+SHORT_DOC_ID already on id=${hit.id}`);
  }
  if (has(item.COMPANY_ID) && has(item.COMPANY_DOC_ID)) {
    const hit = byCompDoc.get(`${norm(item.COMPANY_ID)}||${norm(item.COMPANY_DOC_ID)}`);
    if (hit && hit.id !== resolvedId) collisions.push(`COMPANY_ID+COMPANY_DOC_ID already on id=${hit.id}`);
  }
  if (has(item.HASH)) {
    const hit = byHash.get(norm(item.HASH));
    if (hit && hit.id !== resolvedId) collisions.push(`HASH already on id=${hit.id}`);
  }
  if (collisions.length) {
    stats.rejected++;
    errors.push(`Item #${idx}: uniqueness violation — ${collisions.join('; ')}`);
    continue;
  }

  // build record with type coercion
  const record = {};
  for (const [k, v] of Object.entries(item)) {
    if (STRIP_KEYS.has(k) || k === 'id') continue;
    const { value, warning } = coerce(k, v);
    record[k] = value;
    if (warning) { warnings.push(`Item #${idx}: ${warning}`); stats.coerced++; }
  }
  record.TIMESTAMP = new Date().toISOString();

  if (resolvedId !== null) {
    record.id = resolvedId;
    updatedIds.push(resolvedId);
    console.log(`[${matchMethod}] UPDATE id=${resolvedId}`);
  } else {
    matchMethod = 'create';
    stats.created++;
    console.log(`[create] INSERT (auto id)`);
  }

  records.push(record);
}

console.log(`Upsert ready: total=${stats.total} byId=${stats.byId} byCompShort=${stats.byCompanyShort} byCompDoc=${stats.byCompanyDoc} byHash=${stats.byHash} new=${stats.created} rejected=${stats.rejected} coerced=${stats.coerced}`);

if (!records.length) {
  return [{ json: {
    success: false,
    error: errors.length ? `All ${errors.length} item(s) rejected` : 'No valid records to upsert',
    errors: errors.length ? errors : undefined,
    stats,
    warnings: warnings.length ? warnings : undefined,
    records: [],
    updatedIds: []
  }}];
}

return [{
  json: {
    success: true,
    upsertCount: records.length,
    stats,
    warnings: warnings.length ? warnings : undefined,
    errors: errors.length ? errors : undefined,
    records,
    updatedIds
  }
}];

// Emit one item per updated record so 'process_lock unlock' runs once per id.
// (Mirrors the gsheet workflow which called unlock per UPDATE.)
const prev = $('Resolve & Prepare Records').first().json;
const ids  = Array.isArray(prev.updatedIds) ? prev.updatedIds : [];
if (!ids.length) return [];
return ids.map(id => ({ json: { id: String(id) } }));

// Final summary output — runs in PARALLEL with the unlock side-effect branch
// so it always emits, even when updatedIds is empty (all-INSERT batch).
const prev = $('Resolve & Prepare Records').first().json;
return [{ json: {
  success: true,
  upsertCount: prev.upsertCount,
  updatedCount: (prev.updatedIds || []).length,
  createdCount: prev.stats ? prev.stats.created : 0,
  rejectedCount: prev.stats ? (prev.stats.rejected || 0) : 0,
  coercedCount: prev.stats ? (prev.stats.coerced || 0) : 0,
  stats: prev.stats,
  warnings: prev.warnings,
  errors: prev.errors,
  updatedIds: prev.updatedIds
}}];

return [{ json: {
  success: false,
  error: $json.error || 'Upsert preparation failed'
}}];

// ============================================================================
// BUILD INTROSPECTION SQL — read columns of public."incoming-documents".
// Returns 0 rows if the table doesn't exist.
// ============================================================================

const SUPABASE_PROJECT_REF = 'krvdyzrwstcqrvsaizrk';
const TABLE = 'incoming-documents';

const sql = `select column_name, data_type from information_schema.columns where table_schema = 'public' and table_name = '${TABLE}' order by ordinal_position;`;

return [{ json: {
  url: `https://api.supabase.com/v1/projects/${SUPABASE_PROJECT_REF}/database/query`,
  query: sql
}}];

// ============================================================================
// ANALYZE SCHEMA — single source of truth for the expected table.
// Compares Supabase information_schema rows to EXPECTED list.
//
// Outcomes (`action`):
//   - 'create'   → table missing; build full CREATE TABLE DDL + indexes
//   - 'ok'       → exact match; nothing to do
//   - 'mismatch' → table exists but columns differ; do not modify, report diff
// ============================================================================

const SUPABASE_PROJECT_REF = 'krvdyzrwstcqrvsaizrk';
const TABLE = 'incoming-documents';

// --- EXPECTED SCHEMA -------------------------------------------------------
// 'id' is the Supabase PK (bigint identity). All other columns are derived
// from the jsonExample in the 'When Executed by Another Workflow' trigger
// (which mirrors the gsheet header row) plus type hints by naming convention.
const EXPECTED = {
  id: 'bigint',
  NAME:'text', COMPANY_ID:'text', SHORT_DOC_ID:'text', TYPE:'text', STATUS:'text',
  COMPANY_DOC_ID:'text', LINK:'text', DOC_DATE:'text', PURCHASE_ID:'text',
  SHIPMENT_DOC_ID:'text', BS_LINE_DATE:'text', SOURCE_TYPE:'text', SOURCE_ID:'text',
  SOURCE_LINK:'text', HASH:'text', TIMESTAMP:'text', COMPANY_NAME:'text',
  REQUIRED_ACTION:'text', BS_LINE_NOTE:'text', FROM_OFFICE:'text', API_TOOLS_ID:'text',
  EX_INVOICE_ID:'text', AI_COMPANY_ID:'text', AI_TYPE:'text', AI_DOC_ID:'text',
  AI_DOC_DATE:'text', SELECTED_COMPANY_ID:'text', SELECTED_DOC_ID:'text',
  SELECTED_DOC_DATE:'text', SELECTED_DOC_SHIPMENT_ID:'text', SELECTED_DOC_ORDER_ID:'text',
  SELECTION_SOURCE:'text',
  DOC_TOTAL_AMOUNT:'numeric', BS_LINE_AMOUNT:'numeric', TOTAL_AMOUNT:'numeric',
  AI_DOC_AMOUNT:'numeric', SELECTED_DOC_AMOUNT:'numeric', SIZE:'numeric',
  SELECTION_CERTAINTY:'numeric',
  LINKED_BS:'boolean', BS_EXTRACTION_VERIFIED:'boolean', FROM_OFFICE_CHECK:'boolean',
  BS_LINK_DOCUMENTS_COMPLETED:'boolean', SEARCH_IN_DRIVE_COMPLETED:'boolean',
  DOC_DATE_COMPLETED:'boolean', DOC_TOTAL_AMOUNT_COMPLETED:'boolean',
  PURCHASE_ID_COMPLETED:'boolean', SHIPMENT_ID_COMPLETED:'boolean',
  COMPANY_NAME_COMPLETED:'boolean', API_TOOLS_ID_COMPLETED:'boolean', EMPTY:'boolean',
  BS_EXTRACTED_LINES_COMPLETED:'boolean', BS_EXTRACTION_USE_CACHE:'boolean',
  INVOICE_ID_COMPLETED:'boolean', EX_IS_BS:'boolean', EX_IS_BS_COMPLETED:'boolean',
  FIGURE_TYPE_COMPLETED:'boolean', FIGURE_COMPANY_COMPLETED:'boolean',
  AI_EXTRACTION_COMPLETED:'boolean', PRIORITY_SYNC_COMPLETED:'boolean',
  SELECTION_COMPLETED:'boolean',
  BS_EXTRACTED_LINES:'jsonb', AI_SHIPMENT_IDS:'jsonb', AI_ORDER_IDS:'jsonb',
  DOUBLE_LINE_CONTEXT:'jsonb', SELECTION_SCORE_DEBUG:'jsonb'
};

// --- gather actual columns -------------------------------------------------
const raw = $input.all().map(i => i.json);
let rows = [];
if (raw.length === 1 && Array.isArray(raw[0])) rows = raw[0];
else if (raw.length === 1 && raw[0] && Array.isArray(raw[0].data)) rows = raw[0].data;
else rows = raw;
rows = Array.isArray(rows) ? rows.filter(r => r && r.column_name) : [];

const actual = {};
for (const r of rows) actual[r.column_name] = r.data_type;

// --- build CREATE TABLE DDL (used when table missing) ----------------------
function colDef(name, type) {
  if (name === 'id') return `  "id" bigint generated by default as identity primary key`;
  return `  "${name}" ${type}`;
}
const createCols = Object.entries(EXPECTED).map(([n, t]) => colDef(n, t)).join(',\n');
const createSql = `
create table if not exists "${TABLE}" (
${createCols}
);

create unique index if not exists incoming_documents_company_short_uniq
  on "${TABLE}" ("COMPANY_ID", "SHORT_DOC_ID")
  where "COMPANY_ID" is not null and "SHORT_DOC_ID" is not null;

create unique index if not exists incoming_documents_company_doc_uniq
  on "${TABLE}" ("COMPANY_ID", "COMPANY_DOC_ID")
  where "COMPANY_ID" is not null and "COMPANY_DOC_ID" is not null;

create unique index if not exists incoming_documents_hash_uniq
  on "${TABLE}" ("HASH")
  where "HASH" is not null;
`.trim();

// --- decide action ---------------------------------------------------------
const url = `https://api.supabase.com/v1/projects/${SUPABASE_PROJECT_REF}/database/query`;

if (rows.length === 0) {
  return [{ json: { action: 'create', url, query: createSql, expectedColumnCount: Object.keys(EXPECTED).length } }];
}

const missing   = [];
const extra     = [];
const wrongType = [];

for (const [name, expType] of Object.entries(EXPECTED)) {
  if (!(name in actual)) missing.push({ name, expected: expType });
  else if (actual[name] !== expType) wrongType.push({ name, expected: expType, actual: actual[name] });
}
for (const name of Object.keys(actual)) {
  if (!(name in EXPECTED)) extra.push({ name, type: actual[name] });
}

if (!missing.length && !extra.length && !wrongType.length) {
  return [{ json: { action: 'ok', message: 'Schema matches expectations', columnCount: rows.length } }];
}

return [{ json: {
  action: 'mismatch',
  message: 'Table exists but does not match expected schema',
  missingColumns: missing,
  extraColumns: extra,
  wrongTypeColumns: wrongType,
  expectedColumnCount: Object.keys(EXPECTED).length,
  actualColumnCount: rows.length
}}];

// Report mismatch — DOES NOT modify the table.
const d = $json;
const lines = [];
if (d.missingColumns && d.missingColumns.length)
  lines.push('MISSING (in expected, not in DB):\n' + d.missingColumns.map(c => `  - ${c.name} ${c.expected}`).join('\n'));
if (d.extraColumns && d.extraColumns.length)
  lines.push('EXTRA (in DB, not in expected):\n' + d.extraColumns.map(c => `  - ${c.name} ${c.type}`).join('\n'));
if (d.wrongTypeColumns && d.wrongTypeColumns.length)
  lines.push('WRONG TYPE:\n' + d.wrongTypeColumns.map(c => `  - ${c.name}: expected ${c.expected}, got ${c.actual}`).join('\n'));

return [{ json: {
  success: false,
  action: 'mismatch',
  error: `Table "incoming-documents" exists but does not match expected schema (expected ${d.expectedColumnCount} cols, got ${d.actualColumnCount}). Fix manually or drop & re-run setup.`,
  report: lines.join('\n\n'),
  missingColumns: d.missingColumns,
  extraColumns: d.extraColumns,
  wrongTypeColumns: d.wrongTypeColumns
}}];

// ============================================================================
// BUILD DEDUPE DDL — for each rule, deletes all rows in a duplicate group
// EXCEPT the one with the highest `id` (assumed newest).
// Run BEFORE applying unique indexes when duplicates exist.
// ============================================================================

const SUPABASE_PROJECT_REF = 'krvdyzrwstcqrvsaizrk';
const TABLE = 'incoming-documents';

const sql = `
-- 1. dedupe (COMPANY_ID, SHORT_DOC_ID): keep row with max(id) per group
delete from "${TABLE}" t
using (
  select id
  from (
    select id,
           row_number() over (partition by "COMPANY_ID", "SHORT_DOC_ID" order by id desc) as rn
    from "${TABLE}"
    where "COMPANY_ID" is not null and "SHORT_DOC_ID" is not null
  ) s
  where rn > 1
) d
where t.id = d.id;

-- 2. dedupe (COMPANY_ID, COMPANY_DOC_ID): keep row with max(id) per group
delete from "${TABLE}" t
using (
  select id
  from (
    select id,
           row_number() over (partition by "COMPANY_ID", "COMPANY_DOC_ID" order by id desc) as rn
    from "${TABLE}"
    where "COMPANY_ID" is not null and "COMPANY_DOC_ID" is not null
  ) s
  where rn > 1
) d
where t.id = d.id;

-- 3. dedupe HASH: keep row with max(id) per group
delete from "${TABLE}" t
using (
  select id
  from (
    select id,
           row_number() over (partition by "HASH" order by id desc) as rn
    from "${TABLE}"
    where "HASH" is not null
  ) s
  where rn > 1
) d
where t.id = d.id;

-- 4. now create the unique indexes (safe — duplicates are gone)
create unique index if not exists incoming_documents_company_short_uniq
  on "${TABLE}" ("COMPANY_ID", "SHORT_DOC_ID")
  where "COMPANY_ID" is not null and "SHORT_DOC_ID" is not null;

create unique index if not exists incoming_documents_company_doc_uniq
  on "${TABLE}" ("COMPANY_ID", "COMPANY_DOC_ID")
  where "COMPANY_ID" is not null and "COMPANY_DOC_ID" is not null;

create unique index if not exists incoming_documents_hash_uniq
  on "${TABLE}" ("HASH")
  where "HASH" is not null;
`.trim();

return [{ json: {
  url: `https://api.supabase.com/v1/projects/${SUPABASE_PROJECT_REF}/database/query`,
